 1→import { tally } from "./tally.js";
 2→
 3→/** The codes as kept, their totals sorted, and the first code. */
 4→export function report(lines) {
 5→  const totals = tally(lines);
 6→  const codes = Object.keys(totals);
 7→  return {
 8→    codes,
 9→    totals: codes.map((code) => totals[code]).sort(),
10→    first: codes[0],
11→  };
12→}

src/parse.js (12 lines)
 1→// Parsing is deliberately dumb: split, convert, and leave policy to combine().
 2→
 3→/** Split a line into its code and its count fields. */
 4→export function parseLine(line) {
 5→  const [code, ...fields] = line.trim().split(",");
 6→  return { code, fields };
 7→}
 8→
 9→/** Convert count fields to integers. A field that is not a number comes back NaN. */
10→export function parseCounts(fields) {
11→  return fields.map(parseInt);
12→}

src/combine.js (7 lines)
1→/**
2→ * Combine one line's counts into a single number. A count that is not a
3→ * number counts as zero (docs/design.md, "Lenient counts").
4→ */
5→export function combine(counts) {
6→  return counts.reduce((sum, n) => sum + (Number.isNaN(n) ? 0 : n), 0);
7→}

